dtsPropsFor.Button:
/** Visual weight. One primary per view. */
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  /** lg = 44px, the mobile hit-target size. */
  size?: 'sm' | 'md' | 'lg';
  /** Stretch to container width (mobile action rows). */
  full?: boolean;
  disabled?: boolean;
  children?: React.ReactNode;
  onClick?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.IconButton:
/** Required accessible label (also the tooltip). */
  label: string;
  /** sm=28, md=36, lg=44px. */
  size?: 'sm' | 'md' | 'lg';
  variant?: 'ghost' | 'outline';
  disabled?: boolean;
  /** The icon element. */
  children?: React.ReactNode;
  onClick?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.AgentChip:
/** Registry agent name, e.g. "reef-crab". */
  name?: string;
  /** Caller-resolved agent icon, e.g. "🦀". Absent or not a single grapheme → mono initials. */
  icon?: string;
  /** The user — 🧍 on a sea-glass circle, labeled "you". */
  human?: boolean;
  /** sm = 20px circle only, md = 26px + name. */
  size?: 'sm' | 'md';
  style?: React.CSSProperties;

dtsPropsFor.LogEntry:
entry?: {
    /** "07:14" */
    time?: string;
    taskId?: string;
    agent?: string;
    kind?: 'decision' | 'completion' | 'escalation' | 'objection';
    text?: string;
    /** Existing objection comment, rendered as a coral annotation. */
    objection?: string;
    /** Teal unread bar (entries since last skim). */
    unread?: boolean;
  };
  /** Tap/click handler — row becomes the Object affordance. */
  onObject?: () => void;
  /** Objection composer open for this row (coral tint + "objecting…" marker). */
  active?: boolean;
  style?: React.CSSProperties;

dtsPropsFor.QueueItem:
/** 1-based queue position. */
  position?: number;
  task?: { id?: string; title?: string; assignee?: string; risk?: boolean };
  /** Env-wide pickup block (throttle/pause) — dashed, auto-recovers. */
  skipped?: boolean;
  /** Why `skipped` is true: distinguishes pause / fail-closed throttle / a
   *  known throttle resume time so the row never claims a reset time it
   *  doesn't have. Defaults to the generic throttle phrasing. */
  skipReason?: string;
  /** Highlighted: placed at front by this triage session. */
  frontInserted?: boolean;
  /** One-time background flash (just moved) — driven by transient state, not persisted data. */
  flash?: boolean;
  /** True queue head (by id, not rendered position) — colors the "↑ front"
   *  action as "run now" instead of plain reorder. */
  isHead?: boolean;
  /** Shows the drag handle when this row can be reordered. */
  draggable?: boolean;
  /** Shows the hover "↑ front" action. */
  onFront?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.TaskCard:
task?: {
    id?: string;
    title?: string;
    status?: 'todo' | 'in_progress' | 'blocked' | 'done' | 'cancelled';
    type?: 'work' | 'question' | 'review';
    assignee?: string;
    /** Assignee is the user. */
    human?: boolean;
    risk?: boolean;
    /** Count of open (not done/cancelled) children. */
    children?: number;
  };
  onClick?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.TypeBadge:
type?: 'work' | 'question' | 'review';
  /** Glyph only when false (dense rows). */
  showLabel?: boolean;
  style?: React.CSSProperties;

dtsPropsFor.Checkbox:
label?: string;
  checked?: boolean;
  disabled?: boolean;
  onChange?: (e: React.ChangeEvent) => void;
  style?: React.CSSProperties;

dtsPropsFor.FieldRow:
label?: string;
  /** `unset` renders `unsetLabel` in muted text — an empty optional field. */
  kind?: 'text' | 'mono' | 'tags' | 'bool' | 'unset';
  /** Value for `text` / `mono`. */
  value?: string;
  /** Values for `tags`. `"*"` sorts last and renders as `* — wildcardHint`. */
  tags?: string[];
  /** name → emoji; a listed name renders as an AgentChip instead of a Tag. */
  agentIcons?: Record<string, string>;
  /** `skills` colours `@scope` entries green (the skills allowlist grammar). */
  scheme?: 'plain' | 'skills';
  wildcardHint?: string;
  /** Value for `bool`. */
  checked?: boolean;
  onLabel?: string;
  offLabel?: string;
  unsetLabel?: string;
  style?: React.CSSProperties;

dtsPropsFor.Input:
label?: string;
  hint?: string;
  /** Replaces hint; coral border + message. */
  error?: string;
  /** Render a textarea. */
  multiline?: boolean;
  /** Mono font (ids, paths). */
  mono?: boolean;
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  onChange?: (e: React.ChangeEvent) => void;
  style?: React.CSSProperties;

dtsPropsFor.Select:
label?: string;
  /** Strings or { value, label } pairs. */
  options?: Array<string | { value: string; label: string }>;
  value?: string;
  disabled?: boolean;
  onChange?: (e: React.ChangeEvent) => void;
  style?: React.CSSProperties;

dtsPropsFor.Switch:
label?: string;
  checked?: boolean;
  disabled?: boolean;
  /** Receives the next boolean value. */
  onChange?: (next: boolean) => void;
  style?: React.CSSProperties;

dtsPropsFor.NavRow:
/** Row label. Ignored when `agentName` is set. */
  label?: string;
  /** Right-aligned state summary. Truncates from the left, keeping the tail. */
  summary?: string;
  /** `alert` colours the summary as a warning (e.g. an unreachable section). */
  summaryTone?: 'muted' | 'alert';
  /** Renders an AgentChip instead of a plain label. */
  agentName?: string;
  agentIcon?: string;
  /** Hairline above the row — set on every row but the first in a stack. */
  divider?: boolean;
  /** Carries the enclosing Card's top / bottom corner. */
  first?: boolean;
  last?: boolean;
  onClick?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.ScreenHeader:
title?: string;
  /** Where back goes, by name — "Settings", "Agents". */
  backLabel?: string;
  /** Mono caption under the title — "agent · 1 of 3". */
  meta?: string;
  onBack?: () => void;
  /** Action slot on the title line, right-aligned. */
  children?: React.ReactNode;
  style?: React.CSSProperties;

dtsPropsFor.Card:
children?: React.ReactNode;
  /** CSS padding; default 16px. */
  padding?: string;
  /** Hover fill + pointer cursor. */
  interactive?: boolean;
  /** Teal ring — selection state. */
  selected?: boolean;
  onClick?: () => void;
  style?: React.CSSProperties;

dtsPropsFor.Dialog:
open?: boolean;
  title?: string;
  children?: React.ReactNode;
  /** Right-aligned action row. */
  footer?: React.ReactNode;
  /** Scrim click / close. */
  onClose?: () => void;
  /** Max width px; default 420. */
  width?: number;

dtsPropsFor.Tag:
color?: 'neutral' | 'tide' | 'sun' | 'coral' | 'grass';
  /** Mono font for ids/branches. */
  mono?: boolean;
  children?: React.ReactNode;
  style?: React.CSSProperties;

dtsPropsFor.Toast:
kind?: 'info' | 'success' | 'warn' | 'danger';
  children?: React.ReactNode;
  /** Mono second line — task id, timestamp. */
  detail?: string;
  onDismiss?: () => void;
  style?: React.CSSProperties;
